"use client";

import React, { useEffect, useState } from "react";
import { useNexus, SectionModule } from "@/hooks/useNexusState";
import { ParticleCanvas } from "@/components/core/ParticleCanvas";
import { BootSequence } from "@/components/core/BootSequence";
import { MainNav } from "@/components/core/MainNav";
import { CommandPalette } from "@/components/core/CommandPalette";
import { ToastStack } from "@/components/core/ToastStack";

import { HqSection } from "@/components/modules/hq/HqSection";
import { IdentitySection } from "@/components/modules/identity/IdentitySection";
import { MatrixSection } from "@/components/modules/matrix/MatrixSection";
import { MissionsSection } from "@/components/modules/missions/MissionsSection";
import { VaultSection } from "@/components/modules/vault/VaultSection";
import { CyberLabSection } from "@/components/modules/cyber-lab/CyberLabSection";
import { KnowledgeSection } from "@/components/modules/knowledge/KnowledgeSection";
import { AiAssistant } from "@/components/modules/ai-assistant/AiAssistant";
import { visitorAchievements } from "@/data/achievements";

export default function NexusHomePage() {
  const {
    currentSection,
    booted,
    paletteOpen,
    aiOpen,
    toasts,
    unlockedAchievements,
    setSection,
    setBooted,
    setPaletteOpen,
    setAiOpen,
    addToast,
    removeToast,
    unlockAchievement,
  } = useNexus();

  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Konami Code Easter Egg Listener
  useEffect(() => {
    const konamiSequence = [
      "ArrowUp", "ArrowUp", 
      "ArrowDown", "ArrowDown", 
      "ArrowLeft", "ArrowRight", 
      "ArrowLeft", "ArrowRight", 
      "b", "a"
    ];
    let konamiIndex = 0;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === konamiSequence[konamiIndex]) {
        konamiIndex++;
        if (konamiIndex === konamiSequence.length) {
          unlockAchievement("konami_master");
          addToast({
            title: "Cyber Overdrive Ativado!",
            desc: "Você executou a lendária sequência do Código Konami.",
            icon: "🎮",
          });
          konamiIndex = 0;
        }
      } else {
        konamiIndex = 0;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [unlockAchievement, addToast]);

  // Achievement unlock observer to show toast notification
  const handleUnlock = (achId: string) => {
    if (!unlockedAchievements.includes(achId)) {
      unlockAchievement(achId);
      const ach = visitorAchievements.find((a) => a.id === achId);
      if (ach) {
        addToast({
          title: `Emblema Desbloqueado: ${ach.name}!`,
          desc: ach.desc,
          icon: ach.icon,
        });
      }
    }
  };

  if (!mounted) {
    return (
      <div className="min-h-screen bg-space-deep flex items-center justify-center font-mono text-xs text-cyber-cyan">
        // INICIALIZANDO NEXUS OS v3.0...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-space-deep text-starlight relative flex flex-col justify-between">
      {/* Background Interactive Particle Canvas */}
      <ParticleCanvas />

      {/* Cinematic Boot Sequence (Only runs if not booted yet in session) */}
      {!booted && (
        <BootSequence
          onComplete={() => {
            setBooted(true);
            handleUnlock("first_contact");
          }}
        />
      )}

      {/* Main HUD Top Navigation */}
      <MainNav
        currentSection={currentSection}
        onNavigate={(sec) => {
          setSection(sec);
        }}
        unlockedCount={unlockedAchievements.length}
        totalAchievements={visitorAchievements.length}
        onOpenPalette={() => setPaletteOpen(true)}
      />

      {/* Main Active Section View */}
      <main className="relative z-10 flex-1 py-4">
        {currentSection === "hq" && (
          <HqSection
            onNavigate={(sec) => setSection(sec)}
            onOpenAi={() => setAiOpen(true)}
          />
        )}

        {currentSection === "identity" && (
          <IdentitySection
            onAddToast={addToast}
          />
        )}

        {currentSection === "matrix" && (
          <MatrixSection
            onUnlockAchievement={handleUnlock}
          />
        )}

        {currentSection === "missions" && (
          <MissionsSection
            onUnlockAchievement={handleUnlock}
          />
        )}

        {currentSection === "vault" && (
          <VaultSection
            onUnlockAchievement={handleUnlock}
          />
        )}

        {currentSection === "cyber-lab" && (
          <CyberLabSection
            onUnlockAchievement={handleUnlock}
          />
        )}

        {currentSection === "knowledge" && (
          <KnowledgeSection
            unlockedAchievements={unlockedAchievements}
          />
        )}
      </main>

      {/* System Footer */}
      <footer className="relative z-10 border-t border-border/60 bg-space-deep/90 py-4 px-4 sm:px-8 font-mono text-xs text-asteroid flex flex-wrap items-center justify-between gap-2">
        <div>
          <span>NEXUS OS v3.0 // ARQUITETURA NEXT.JS 15</span>
        </div>
        <div>
          <span className="text-starlight">Gabriel Henrique Alves Rocha</span> © {new Date().getFullYear()}
        </div>
      </footer>

      {/* Command Palette HUD (Ctrl+K) */}
      <CommandPalette
        open={paletteOpen}
        onOpenChange={setPaletteOpen}
        onNavigate={(sec) => setSection(sec)}
        onOpenAi={() => setAiOpen(true)}
        onAddToast={addToast}
        onUnlockAchievement={handleUnlock}
      />

      {/* Floating AI Cognitive Copilot */}
      <AiAssistant
        open={aiOpen}
        onOpenChange={setAiOpen}
        onUnlockAchievement={handleUnlock}
      />

      {/* Toast Notification Stack */}
      <ToastStack
        toasts={toasts}
        onDismiss={removeToast}
      />
    </div>
  );
}
